command:
/bin/bash -lc "set +e
for cmd in \\
  'env -u DELEGATE_WORKFLOW_PIN -u PYTHONPATH python3 -m unittest tests.test_proc_harness -v' \\
  'env -u DELEGATE_WORKFLOW_PIN -u PYTHONPATH python3 -m unittest tests.test_workflow_watchdog tests.test_workflow_watchdog_unit -v' \\
  'TMPDIR=/tmp env -u DELEGATE_WORKFLOW_PIN -u PYTHONPATH sh tests/acceptance.sh'; do
  echo \"--- "'$cmd";
  sh -c "$cmd";
  rc=$?; echo "exit=$rc";
done
exit 0'

/bin/bash -lc "python3 -m py_compile tests/test_proc_harness.py tests/proc_harness.py && python3 - <<'PY'
from pathlib import Path
for line in Path('tests/test_proc_harness.py').read_text().splitlines():
    if 'child = subprocess' in line:
        print(line)
PY"
